do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'algebra-1';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: Cumulative Problem Set$j$, $j${"prompt": "Show every step for each item. (1) Simplify (2x³)(3x²) and write 5² · 5³ as a power of 5. (2) Simplify √48. (3) Multiply (x + 3)(x − 2). (4) Solve 3x − 7 = 11 and solve 2x + 5 < 11, and graph the inequality's solution on a number line in words. (5) Solve |x − 2| = 5. (6) Find the slope of the line through (1, 2) and (3, 8) and write its equation. (7) Solve the system y = 2x + 1 and x + y = 7 and check the solution. (8) Factor x² + 3x − 10 and solve x² − 5x + 6 = 0. (9) For y = x² − 4x + 3, give the axis, vertex and zeros. (10) A balance of $1,000 earns 5% interest compounded yearly. Write the model and find the balance after 2 years. (11) For the data 4, 6, 8, 10, 12, 14, find the mean, median and IQR. (12) In two or three sentences, explain how you used one concept from this course in a real situation, and give glory to God for the gift of learning.", "rubric": "Total 100. Items 1 to 11 are worth 8 each (answer 5, work 3) for 88. Item 12 is worth 12 (relevant concept 4, clear explanation 4, reflection 4). Expected answers: 1) 6x⁵, 5⁵; 2) 4√3; 3) x² + x − 6; 4) x = 6 and x < 3; 5) x = 7 or x = −3; 6) slope 3, y = 3x − 1; 7) (2, 5); 8) (x + 5)(x − 2), and x = 2 or x = 3; 9) axis x = 2, vertex (2, −1), zeros 1 and 3; 10) A = 1000(1.05)ᵗ, $1,102.50; 11) mean 9, median 9, IQR 6. A score of 70 or better is required to pass."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: Cumulative Problem Set$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: Algebra 1$j$, $j${"questions": [{"q": "Simplify (2x³)(3x²).", "options": ["5x⁶", "5x⁵", "6x⁵", "6x⁶"]}, {"q": "Simplify √48.", "options": ["2√6", "6√2", "16√3", "4√3"]}, {"q": "Multiply (x + 3)(x − 2).", "options": ["x² + x + 6", "x² − 6", "x² + x − 6", "x² − x − 6"]}, {"q": "Solve 3x − 7 = 11.", "options": ["x = 4", "x = 12", "x = 6", "x = 18"]}, {"q": "Solve |x − 2| = 5.", "options": ["x = 3 or x = −7", "x = 5 or x = −5", "x = 7 only", "x = 7 or x = −3"]}, {"q": "What is the slope of the line through (1, 2) and (3, 8)?", "options": ["2", "6", "3", "1/3"]}, {"q": "Solve the system y = 2x + 1 and x + y = 7.", "options": ["(2, 5)", "(3, 7)", "(1, 3)", "(6, 1)"]}, {"q": "Solve x² − 5x + 6 = 0.", "options": ["x = 1 or x = 6", "x = −1 or x = 6", "x = −2 or x = −3", "x = 2 or x = 3"]}, {"q": "What is the vertex of y = x² − 4x + 3?", "options": ["(4, 3)", "(−2, −1)", "(2, −1)", "(2, 1)"]}, {"q": "A balance of $1,000 earns 5% interest compounded yearly. What is the balance after 2 years?", "options": ["$1,102.50", "$1,050.00", "$1,100.00", "$1,250.00"]}, {"q": "Solve 2x + 5 < 11.", "options": ["x < 8", "x > 3", "x < 3", "x > 8"]}, {"q": "If f(x) = x² − 3x, what is f(−2)?", "options": ["−10", "10", "−2", "2"]}, {"q": "Factor x² + 3x − 10.", "options": ["(x − 5)(x + 2)", "(x + 5)(x − 2)", "(x + 5)(x + 2)", "(x − 5)(x − 2)"]}, {"q": "What is the mean of 4, 6, 8, 10, 12, 14?", "options": ["8", "9", "10", "54"]}, {"q": "A scatter plot has points that rise from left to right. The correlation is:", "options": ["Zero", "Positive", "Undefined", "Negative"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Algebra 1$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,2,2,3,2,0,3,2,0,2,1,1,1,1}'::int[], array[$j$Multiply coefficients and add exponents.$j$,$j$√48 = √16 · √3 = 4√3.$j$,$j$x² − 2x + 3x − 6 = x² + x − 6.$j$,$j$3x = 18, so x = 6.$j$,$j$x − 2 = 5 or x − 2 = −5.$j$,$j$(8 − 2)/(3 − 1) = 3.$j$,$j$x + 2x + 1 = 7 gives x = 2 and y = 5.$j$,$j$(x − 2)(x − 3) = 0.$j$,$j$The axis is x = 2 and y(2) = −1.$j$,$j$1000(1.05)² = 1102.50.$j$,$j$2x < 6, so x < 3.$j$,$j$4 + 6 = 10.$j$,$j$5 and −2 multiply to −10 and add to 3.$j$,$j$The sum is 54, and 54/6 = 9.$j$,$j$Rising points show positive correlation.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Algebra 1$j$ on conflict (item_id) do nothing;
end
$seed$;
